-- C-125: own photos for eight hotels that showed the city photo (contact-sheet picks, licensed
-- Wikimedia Commons / Flickr images, self-hosted in apps/web/public/hotels). image_url feeds OG
-- cards and emails (1280 px where the source is larger), image_credit is shown next to the photo.
update public.hotels h
set image_url = v.image_url, image_credit = v.image_credit, image_source_url = v.image_source_url
from (values
  ('sofitel-frankfurt-opera', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Frankfurt%2C_Opernplatz%2C_k%C3%BCnftiges_Sofitel_Hotel.JPG/1280px-Frankfurt%2C_Opernplatz%2C_k%C3%BCnftiges_Sofitel_Hotel.JPG', 'Foto: Karsten Ratzke, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Frankfurt,_Opernplatz,_k%C3%BCnftiges_Sofitel_Hotel.JPG'),
  ('mandarin-oriental-hong-kong', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Mandarin_Oriental_Hong_Kong_Lobby_Stairs_2008.jpg/1280px-Mandarin_Oriental_Hong_Kong_Lobby_Stairs_2008.jpg', 'Foto: Wpcpey, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/w/index.php?curid=49332967'),
  ('rosewood-hong-kong', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Rosewood_Hong_Kong_Level_6_Swimming_Pool_2020.jpg/1280px-Rosewood_Hong_Kong_Level_6_Swimming_Pool_2020.jpg', 'Foto: Wpcpey, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/w/index.php?curid=97520983'),
  ('the-beverly-hills-hotel-los-angeles', 'https://live.staticflickr.com/2313/2086903257_e2c368b147_b.jpg', 'Foto: Alan Light, CC BY 2.0, via Flickr', 'https://www.flickr.com/photos/42274165@N00/2086903257'),
  ('the-peninsula-beverly-hills-los-angeles', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/The_Peninsula_Beverly_Hills_2015.jpg/1280px-The_Peninsula_Beverly_Hills_2015.jpg', 'Foto: Toglenn, CC BY-SA 3.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_Peninsula_Beverly_Hills_2015.jpg'),
  ('mandarin-oriental-milan', 'https://live.staticflickr.com/65535/54031209917_fb7881733d_b.jpg', 'Foto: yanayrosen, Public Domain Mark, via Flickr', 'https://www.flickr.com/photos/187878392@N04/54031209917'),
  ('hotel-de-russie-rom', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Hotel_de_Russie_in_Rome_%281819-1822%29_-_GUESTS_P%C3%ABtr_Ilic_Ciaikovski_%281879%29%2C_Pablo_Picasso_with_Igor_Stravinsky_%281917%29._Here_died_Napoleone_Giuseppe_Carlo_Bonaparte_%28J%C3%A9r%C3%B4me%2C_Trieste_1822-Rome_1891%29%2C_Napoleon%27s_nephew._%2829113995990%29.jpg/1280px-Hotel_de_Russie_in_Rome_%281819-1822%29_-_GUESTS_P%C3%ABtr_Ilic_Ciaikovski_%281879%29%2C_Pablo_Picasso_with_Igor_Stravinsky_%281917%29._Here_died_Napoleone_Giuseppe_Carlo_Bonaparte_%28J%C3%A9r%C3%B4me%2C_Trieste_1822-Rome_1891%29%2C_Napoleon%27s_nephew._%2829113995990%29.jpg', 'Foto: Carlo Raso from Naples, Italy, Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hotel_de_Russie_in_Rome_(1819-1822)_-_GUESTS_P%C3%ABtr_Ilic_Ciaikovski_(1879),_Pablo_Picasso_with_Igor_Stravinsky_(1917)._Here_died_Napoleone_Giuseppe_Carlo_Bonaparte_(J%C3%A9r%C3%B4me,_Trieste_1822-Rome_1891),_Napoleon%27s_nephew._(29113995990).jpg'),
  ('hotel-eden-rom', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Hotel_Eden_-_Dorchester_Collection2.jpg/1280px-Hotel_Eden_-_Dorchester_Collection2.jpg', 'Foto: PatriaDeTodos, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/w/index.php?curid=123643710')
) as v (slug, image_url, image_credit, image_source_url)
where h.slug = v.slug;
